<script>
const titles={dashboard:['Retail overview','Everything important from your stores, vendors and sales.'],pos:['Touch Billing','Fast counter billing with multi-payment, discounts and returns.'],vendors:['Vendors','Manage vendor catalogues, commissions, status and performance.'],products:['Products','Item master, pricing rules, images, classifications and stock.'],orders:['Orders','Sales orders, delivery notes, returns and exchanges.'],purchase:['Purchase','Purchase orders, supplier receipts and purchase transactions.'],inventory:['Inventory','Live stock movement, transfers, adjustments and reorder alerts.'],accounting:['Accounting','Receivables, payables, ledgers, payments and daily closing.'],reports:['Reports & Charts','Sales, purchase, stock, profit and vendor analytics.'],settings:['Settings','Store configuration, invoice series, users and integrations.']};
function show(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===id));document.getElementById('pageTitle').textContent=titles[id][0];document.getElementById('pageSub').textContent=titles[id][1];if(id==='pos')renderCatalog()}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));
const items=[['👟','Everyday Runner Shoes',1499,'Style Street'],['🎧','Wireless Headphones',2199,'Tech Corner'],['👜','Everyday Tote Bag',899,'Urban Mart'],['🪴','Minimal Plant Pot',549,'HomeNest'],['⌚','Smart Watch',3299,'Tech Corner'],['👕','Cotton Overshirt',1299,'Urban Mart']];let cart=[];
function renderCatalog(){const el=document.getElementById('catalog');if(!el)return;el.innerHTML=items.map((x,i)=>`<div class="item" onclick="add(${i})"><span class="emoji">${x[0]}</span><b>${x[1]}</b><small>${x[3]} · ₹${x[2].toLocaleString('en-IN')}</small></div>`).join('');renderCart()}
function add(i){const x=items[i],found=cart.find(a=>a.i===i);found?found.q++:cart.push({i,q:1});renderCart()}
function renderCart(){const el=document.getElementById('cart');if(!el)return;el.innerHTML=cart.length?cart.map(a=>{let x=items[a.i];return `<div class="cartrow"><div><b>${x[1]}</b><small style="display:block;color:var(--muted)">₹${x[2].toLocaleString('en-IN')}</small></div><div class="qty"><button onclick="change(${a.i},-1)">−</button><b>${a.q}</b><button onclick="change(${a.i},1)">+</button></div><b>₹${(x[2]*a.q).toLocaleString('en-IN')}</b></div>`}).join(''):'<p class="sub">Tap products to add them to the bill.</p>';let total=cart.reduce((s,a)=>s+items[a.i][2]*a.q,0);document.getElementById('subtotal').textContent='₹'+total.toLocaleString('en-IN');document.getElementById('grand').textContent='₹'+total.toLocaleString('en-IN');document.getElementById('charge').textContent=total.toLocaleString('en-IN')}
function change(i,d){let a=cart.find(x=>x.i===i);if(a){a.q+=d;if(a.q<1)cart=cart.filter(x=>x.i!==i)}renderCart()}function clearCart(){cart=[];renderCart()}function checkout(){let total=cart.reduce((s,a)=>s+items[a.i][2]*a.q,0);if(!total)return alert('Add an item first.');alert('Payment screen ready for ₹'+total.toLocaleString('en-IN')+' — Cash / UPI / Card / Split Payment.');clearCart()}
const gs=document.getElementById('globalSearch');gs.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.product,.item,.vendor,.order,.table tr').forEach(el=>{if(el.querySelector('th'))return;el.style.display=!q||el.textContent.toLowerCase().includes(q)?'':'none'})});
renderCatalog();
</script></body></html>